SAKE.FIGINDEX = [{"p":"index","n":1,"c":{"en":"Multiple parallel fermentation.","ja":"並行複発酵。麹菌（Aspergillus oryzae）の酵素が米のデンプンをブドウ糖に分解し、酵母（Sacc…","zh":"並行複發酵。麴菌（Aspergillus oryzae）分泌酵素將米澱粉切成葡萄糖，酵母（Saccharomy…"}},{"p":"start","n":1,"c":{"en":"The six bottles as a single experiment.","ja":"六本を、一つの実験として。","zh":"六瓶酒，作為單一的一場實驗。"}},{"p":"myths","n":1,"c":{"en":"What the law lets into a bottle of seishu, measured against the weight of the rice.","ja":"法が清酒の一本のうちに許すものを、米の重量に対して測ったもの。","zh":"法律允許進入一瓶清酒的東西，以米的重量為尺度衡量。"}},{"p":"history","n":1,"c":{"en":"The four threads laid on one axis, with a break at 1600 because almost everything happened after it.","ja":"四つの通奏低音を一本の軸に置いたもの。","zh":"四條線索並置於同一條軸上，並在一六〇〇年處折斷——因為幾乎一切都發生在那之後。"}},{"p":"people","n":1,"c":{"en":"Nine lives against one axis.","ja":"九つの生涯を、一本の軸に当てたもの。","zh":"九段人生，放在同一條軸上。"}},{"p":"women","n":1,"c":{"en":"The industry has two halves and they are not the same shape.","ja":"この産業には二つの半分があり、その形は同じでない。","zh":"這個產業有兩個半邊，而它們的形狀並不相同。"}},{"p":"culture","n":1,"c":{"en":"Why the evening has rounds.","ja":"なぜ夜には次があるのか。この構えは偶然ではなく、また日本だけのものでもないが、日本はその各段に名を持っている。","zh":"為什麼一個晚上會有好幾攤。"}},{"p":"shinto","n":1,"c":{"en":"The year as a brewery experiences it.","ja":"蔵が経験するところの一年。","zh":"一家酒藏所經歷的一年。網底的弧是寒造的釀造季；弧外的記號是祭典。"}},{"p":"shinto","n":2,"c":{"en":"The common order, and the sake's place in it.","ja":"よくある順と、そのなかの酒の位置。","zh":"常見的次序，以及酒在其中的位置。"}},{"p":"poetry","n":1,"c":{"en":"The thirteen poems as a sequence of moves rather than thirteen separate poems.","ja":"十三首を、十三の別々の歌としてではなく、手の連なりとして見たもの。","zh":"把這十三首看成一連串的「動作」，而不是十三首各自獨立的歌。"}},{"p":"words","n":1,"c":{"en":"The Japanese scale of drinking capacity, with the nearest Chinese expressions beneath.","ja":"日本語における酒量の目盛り。","zh":"日語裡的酒量刻度，下方附上最接近的中文說法。"}},{"p":"words","n":2,"c":{"en":"The six named stages against blood alcohol concentration, with the amount of sake that typically produces each.","ja":"名を持つ六つの段階を、血中アルコール濃度に対して置き、それぞれを典型的に生じる酒の量を添えたもの。","zh":"六個具名階段對應血中酒精濃度，並附上通常會造成各階段的清酒量。"}},{"p":"translation","n":1,"c":{"en":"One example of each failure mode, with the two destination languages side by side.","ja":"それぞれの失敗の道の例を一つずつ、二つの行き先の言語を並べて示す。","zh":"每一種失敗方式各舉一例，並把兩種目標語言並置。"}},{"p":"translation","n":2,"c":{"en":"One mouthful, read twice.","ja":"ひと口を、二度読む。上の括りは日本語の語、下は英語である。","zh":"同一口酒，被讀了兩次。上方的括弧是日文詞，下方是英文。"}},{"p":"media","n":1,"c":{"en":"Everything on this page, on one line.","ja":"この頁のすべてを一本の線に置いたもの。","zh":"把這一頁上的一切放在同一條線上。"}},{"p":"compare","n":1,"c":{"en":"Wine has sugar already.","ja":"ワインには最初から糖がある。","zh":"葡萄酒本來就有糖。啤酒先造糖，再發酵。"}},{"p":"ingredients","n":1,"c":{"en":"A cross-section of a sake rice grain.","ja":"酒米の断面。たんぱく質と脂質は表層に向かって集中し、白く粗な心白は中心にある。","zh":"酒米粒的斷面。蛋白質與脂質向表層集中，粗鬆的心白位於中心。"}},{"p":"rice","n":1,"c":{"en":"The main line of descent.","ja":"主たる系譜である。実線は交配、破線は突然変異による選抜、あるいは他方の親がこの図の外にある系統を示す。","zh":"主要的血緣譜系。實線代表雜交；虛線代表突變選育，或另一方親本不在本圖之內的系統。"}},{"p":"milling","n":1,"c":{"en":"A grain of sake rice in section, with the layers named and the polishing ratios marked as the depths at which they ar…","ja":"酒米の粒の断面。層に名を付し、精米歩合を、それらが失われる深さとして記した。","zh":"酒米米粒的剖面，標出各層名稱，並把精米步合標示為「這些層在何種深度消失」。"}},{"p":"milling","n":2,"c":{"en":"How long the mill runs.","ja":"精米機がどれだけ回るか。曲線は線形ではなく、線形に近くもない。","zh":"精米機要運轉多久。這條曲線不是線性的，而且離線性很遠：最後那幾個百分點所花的時間，比最前面的三十點還要長——因…"}},{"p":"milling","n":3,"c":{"en":"The same grain, the same weight removed, three ways.","ja":"同じ粒、同じ重さを、三つの仕方で。","zh":"同一顆米粒、削去同樣的重量，三種做法。"}},{"p":"milling","n":4,"c":{"en":"Every polishing ratio published by the two hundred and twelve houses in the directory, counted once per figure printe…","ja":"名鑑に載る二百十二の蔵が公表している精米歩合のすべてを、酒標に刷られた数ごとに一度数えたもの。","zh":"名鑑中兩百一十二家酒藏所公布的每一個精米步合，依酒標上印出的每個數字各計一次。"}},{"p":"ricepolicy","n":1,"c":{"en":"The grading ladder for brewing brown rice.","ja":"醸造用玄米の等級の梯子。棒は、その一山が達せねばならぬ整粒の最小の割合であり、右の数は許される被害粒の最大の割…","zh":"釀造用玄米的等級階梯。長條是一批米必須達到的整粒最低比例；右邊的數字是容許的受損粒最高比例。"}},{"p":"ricepolicy","n":2,"c":{"en":"Four gates, and the label is silent unless all four are open.","ja":"四つの門があり、その四つがすべて開かぬ限り札は黙る。","zh":"四道門，四道都打開之前，酒標保持沉默。"}},{"p":"water","n":1,"c":{"en":"Why the wells sit where they do, drawn as a section from Mount Rokkō to Osaka Bay.","ja":"井戸がなぜその場所にあるのかを、六甲山から大阪湾までの断面として描いたもの。","zh":"井為何座落於此——以自六甲山至大阪灣的剖面來說明。"}},{"p":"koji","n":1,"c":{"en":"A typical ginjō kōji cycle.","ja":"典型的な吟醸麹の一巡。線を押し上げるのは菌自身の代謝熱であり、名を持つ各工程は、それを再び寝かせる物理的な介入…","zh":"一次典型的吟釀麴週期。推升曲線的是麴菌自身的代謝熱，而每一道有名字的工序，都是讓它再度趨平的物理介入。"}},{"p":"yeast","n":1,"c":{"en":"The association strains placed against each other.","ja":"協会の株を互いに対して置いたもの。","zh":"把協會各菌株彼此對照放置。"}},{"p":"process","n":1,"c":{"en":"A ginjō fermentation over about thirty days.","ja":"およそ三十日の吟醸醪。ボーメ（比重の読み値であり残糖に比例する）は下がり、アルコールは上がる。","zh":"約三十天的吟釀醪。波美度（比重讀數，與殘糖成正比）下降，酒精上升；溫度被刻意壓低，而釀造者所允許的峰值，正是吟…"}},{"p":"starters","n":1,"c":{"en":"The three starter methods on one thirty-day axis.","ja":"三十日の一つの軸に置いた三つの酒母法。","zh":"置於同一條三十日軸線上的三種酒母工法。"}},{"p":"pressing","n":1,"c":{"en":"One pressing, read left to right in the order the liquid comes out.","ja":"一度の上槽を、液の出る順に左から右へ読む。","zh":"一次上槽，依酒液流出的順序由左至右閱讀。"}},{"p":"equipment","n":1,"c":{"en":"A traditional kura in section.","ja":"伝統的な蔵の断面。その設計は、三層を貫く一つの考えである——米は最上階から入り、その後のあらゆる工程はそれを下…","zh":"傳統酒藏的剖面。它的配置貫徹著單一個想法：米從最上層進入，之後每一道工序都把它往下送，因此任何東西都不必逆著重…"}},{"p":"equipment","n":2,"c":{"en":"The tasting cup, seen from above.","ja":"利き猪口を上から見たもの。","zh":"從上方看的利き猪口。白瓷，底部燒上兩圈同心的藍環；在日本任何一家酒藏、任何一個評鑑會場，它都是同樣的形狀與同樣…"}},{"p":"toji","n":1,"c":{"en":"Where the guilds came from and where they went.","ja":"集団がどこから来て、どこへ行ったか。","zh":"這些集團從哪裡來、又往哪裡去。"}},{"p":"calendar","n":1,"c":{"en":"The brewing year read clockwise from July.","ja":"七月から時計回りに読む酒造年度。","zh":"從七月開始順時針閱讀的酒造年度。"}},{"p":"batch","n":1,"c":{"en":"The mass balance of a one-tonne junmai batch, with every bar on the same scale.","ja":"総米一トンの純米仕込みの物質収支。","zh":"一公噸純米仕込的物料平衡，所有長條使用同一比例尺。"}},{"p":"batch","n":2,"c":{"en":"A schematic mash curve for a junmai ginjō.","ja":"純米吟醸の醪経過の模式図。","zh":"一支純米吟釀的醪經過示意圖。"}},{"p":"batch","n":3,"c":{"en":"Rice to alcohol, by mass, with the two exact steps in the middle.","ja":"米からアルコールまでを質量で追い、その中ほどに正確な二段を置いたもの。","zh":"從米到酒精，以質量追蹤，中間放進兩個精確的步驟。"}},{"p":"microbes","n":1,"c":{"en":"The succession in a kimoto, drawn as populations over a month.","ja":"生酛における遷移を、一月にわたる集団の変化として描いたもの。","zh":"生酛中的演替，畫成一個月裡的族群消長。"}},{"p":"classification","n":1,"c":{"en":"The eight special designations as a grid.","ja":"八つの特定名称を格子として。","zh":"把八種特定名稱畫成一張格子。"}},{"p":"label","n":1,"c":{"en":"Front label and statutory back panel, with the ten elements numbered.","ja":"表ラベルと裏の法定表示欄。","zh":"正面酒標與背面法定標示欄，十個元素均已編號。"}},{"p":"design","n":1,"c":{"en":"A 720 mL bottle with its dress named.","ja":"七二〇ミリリットルの瓶と、その装いの名。","zh":"一支 720 毫升的瓶子，以及它身上各件衣裝的名字。"}},{"p":"design","n":2,"c":{"en":"Seven schematic front labels, one per era.","ja":"時代ごとに一枚ずつ、七枚の模式的な胴貼。","zh":"七張示意性的胴標，每個時代一張。"}},{"p":"styles","n":1,"c":{"en":"Two axes: aroma intensity on the vertical, flavour weight on the horizontal.","ja":"二つの軸——縦軸に香りの強さ、横軸に味の濃さ。","zh":"兩個軸向：縱軸為香氣強度，橫軸為風味厚度。"}},{"p":"numbers","n":1,"c":{"en":"The two numbers that appear on almost every analysis, plotted against each other.","ja":"ほとんどあらゆる分析に現れる二つの数を、互いに対して描いたもの。","zh":"幾乎每一份分析表上都會出現的兩個數字，彼此對照繪出。"}},{"p":"taste","n":1,"c":{"en":"The two formulas plotted as a plane.","ja":"二つの式を平面として描いたもの。","zh":"把兩道公式畫成一個平面。橫軸是日本酒度，縱軸是酸度，兩條線分別是各指標等於零之處——甘辛的分界與濃淡的分界。"}},{"p":"standards","n":1,"c":{"en":"The whole of the 1989 designation table as a grid.","ja":"一九八九年の特定名称の表の全体を、一枚の格子にしたもの。","zh":"把一九八九年特定名稱表的全部內容化為一張格子。"}},{"p":"fakes","n":1,"c":{"en":"Four things that were done to sake, drawn against the years they were done in.","ja":"酒に対して行われた四つのことを、それが行われた年に対して描いたもの。","zh":"四件曾經對酒做過的事，畫在它們發生的年份之上。"}},{"p":"fakes","n":2,"c":{"en":"Why the grade system destroyed itself.","ja":"級別制度がみずから壊れた理由。","zh":"等級制度為何自我毀滅。送審是自願的，而從未送審的酒依預設就是二級——適用二級稅率。"}},{"p":"aging","n":1,"c":{"en":"The same sake, kept three ways, drawn as the colour it would be at each point.","ja":"同じ酒を三通りに置いたとき、それぞれの時点で帯びているであろう色を描いたもの。","zh":"同一支酒以三種方式保存，畫出它在各個時點應有的顏色。"}},{"p":"sparkling","n":1,"c":{"en":"Pressure at 20 °C, which is the one number that separates these drinks from each other.","ja":"二十度における圧。これらの飲みものを互いに分かつ、ただ一つの数である。","zh":"二十度下的壓力——這是把這些飲品彼此分開的唯一數字。"}},{"p":"packaging","n":1,"c":{"en":"The standard containers, drawn to the same scale.","ja":"標準の容器を、同じ縮尺で描いたもの。","zh":"標準容器，以同一比例尺繪出。"}},{"p":"kanji","n":1,"c":{"en":"The jar and its descendants.","ja":"壺と、その裔たち。酉は、括れた首と膨らんだ胴と横の帯を持つ器として甲骨に描かれ、以来ずっと、醸された液を表す意…","zh":"酒壺，與它的後裔。「酉」在甲骨上被畫成一只細頸、鼓腹、帶橫紋的容器，自此便一直是表示「發酵液體」的意符；下列各…"}},{"p":"sustainability","n":1,"c":{"en":"Two accounts a brewery rarely publishes together.","ja":"蔵が同じ頁に並べて出すことの稀な、二つの勘定。","zh":"兩份酒藏很少並列公布的帳。"}},{"p":"sustainability","n":2,"c":{"en":"One batch, and the two things the brewery is paying for.","ja":"一仕込みと、蔵が支払っている二つのもの。","zh":"一次仕込，以及酒藏正在為之付錢的兩件事。"}},{"p":"faults","n":1,"c":{"en":"The three routes and the named faults each produces, with the responsible compound set beneath each name.","ja":"三つの道筋と、それぞれが生む名づけられた欠点。","zh":"三條路徑，以及各自產生的、有名字的缺點；每個名字下方是造成它的物質。"}},{"p":"homebrew","n":1,"c":{"en":"Roughly how much alcohol a private person may legally make at home for their own use, per year.","ja":"私人が自ら飲むために、家で合法に造りうる酒の量のおおよそ。","zh":"私人為自用而能在家中合法製造的酒量大致有多少，以年計。"}},{"p":"terroir","n":1,"c":{"en":"The two axes that do most of the sorting, with the districts placed against each other.","ja":"最も多くを分けている二つの軸と、その上に互いに対して置かれた地区。","zh":"承擔最多分類工作的兩條軸線，以及各產地在其上的相對位置。"}},{"p":"regions","n":1,"c":{"en":"The forty-seven prefectures as a tile grid, grouped by brewing school.","ja":"四十七都道府県をタイルの格子として、醸造の流派ごとに配した図。","zh":"以方格排列的四十七個都道府縣，依釀造流派分組。"}},{"p":"region-north","n":1,"c":{"en":"Seven prefectures, seven rices, and a single decade.","ja":"七つの県、七つの米、そして一つの十年。","zh":"七個縣、七種米，以及同一個十年。"}},{"p":"region-central","n":1,"c":{"en":"Yamanashi has very few sake breweries and an outsized place in Japanese drinks, and the reason is one line of hydrolo…","ja":"山梨には日本酒の蔵がごく少なく、それでいて日本の酒のなかで不釣り合いなほど大きな位置を占める。","zh":"山梨的清酒酒藏極少，卻在日本的酒類版圖中占據不成比例的位置，而理由是一條水文線。"}},{"p":"region-hokuriku","n":1,"c":{"en":"Two or three metres of snow, and what a brewery does with it.","ja":"二、三メートルの雪と、蔵がそれで何をするか。","zh":"兩三公尺的雪，以及一家酒藏拿它來做什麼。"}},{"p":"region-kinki","n":1,"c":{"en":"Why the largest brewing region in Japanese history stopped being the centre of the subject.","ja":"日本の歴史において最大の酒どころが、なぜ主題の中心であることをやめたのか。","zh":"日本歷史上最大的釀造地區，為何不再是這門主題的中心。"}},{"p":"region-west","n":1,"c":{"en":"Why Hiroshima had to invent something.","ja":"広島がなにかを編み出さねばならなかった理由。","zh":"廣島為什麼非得發明點什麼。"}},{"p":"region-kyushu","n":1,"c":{"en":"The most useful map of Japanese fermentation is not a map at all but a line between two moulds.","ja":"日本の醸しについて最も役に立つ地図は、地図ではなく、二つの麹のあいだの一本の線である。","zh":"關於日本發酵，最有用的地圖其實不是地圖，而是兩種麴之間的一條線。"}},{"p":"gi","n":1,"c":{"en":"Every sake GI, in the order it was registered.","ja":"清酒のGIのすべてを、登録された順に。","zh":"所有清酒 GI，依註冊先後排列。"}},{"p":"breweries","n":1,"c":{"en":"The four scales of brewery on one axis.","ja":"四つの規模の蔵を、一本の軸の上に置いたもの。","zh":"四種規模的酒藏，放在同一條軸上。"}},{"p":"brands","n":1,"c":{"en":"When each pattern is at its strongest.","ja":"それぞれの型が最も強く働く時期。","zh":"每一種模式最強勢的時期。這六個系統並不互相取代——每一種至今都仍在使用——但每一種都有一段時期，在那段時期裡用…"}},{"p":"tasting","n":1,"c":{"en":"Two routes to the same receptors.","ja":"同じ受容体へ至る二つの道。","zh":"通往同一組受體的兩條路徑。"}},{"p":"curriculum","n":1,"c":{"en":"The whole programme as a grid.","ja":"献立の全体を一つの格子として。","zh":"整套課程作為一張格子。兩瓶清酒之間可以不同的事情有十件；每一列只把「那一週被允許不同的那一件」塗深，該列的其他…"}},{"p":"serving","n":1,"c":{"en":"The ten named temperatures on one scale.","ja":"十の名を持つ温度を一つの尺度に置いた。","zh":"把十個具名的溫度放在同一把尺上。"}},{"p":"vessels","n":1,"c":{"en":"Seven vessels in cross-section, drawn to one scale, each holding the amount it is normally filled with.","ja":"七つの器を断面で、同じ縮尺で描き、それぞれ普段満たされる量を入れたもの。","zh":"七只器皿的剖面，以同一比例尺繪出，各自盛著平常會斟到的份量。"}},{"p":"pairing","n":1,"c":{"en":"The four differences, measured.","ja":"四つの違いを、測って並べたもの。","zh":"把四項差異量出來並列。其中三項是減法——清酒幾乎不含單寧、酸只有零頭、也沒有葡萄酒那種構成骨架的苦味——而減法…"}},{"p":"storage","n":1,"c":{"en":"A schematic of the same bottle stored three ways.","ja":"同じ一本を三通りに貯えた場合の模式図。","zh":"同一支酒以三種方式保存的示意圖。"}},{"p":"range","n":1,"c":{"en":"A typical mid-sized brewery's range on its two real axes.","ja":"中ほどの大きさの蔵の品揃えを、その実の二軸に置いたもの。","zh":"一家中型酒藏的產品線，放在它真正的兩條軸上。"}},{"p":"range","n":2,"c":{"en":"When each seasonal name is actually on the shelf.","ja":"季節の名がそれぞれ、実際にいつ棚にあるか。","zh":"每一個季節名稱實際上在貨架上出現的時間。"}},{"p":"value","n":1,"c":{"en":"Japanese shelf prices for 720 mL, by category, on a logarithmic scale.","ja":"七百二十ミリリットルの日本国内の棚の値を、区分ごとに、対数の目盛りの上に置いたもの。","zh":"七百二十毫升在日本的架上價，依類別排列，繪於對數刻度上。"}},{"p":"value","n":2,"c":{"en":"The brown rice standing behind one 720 mL bottle, worked out from the mass balance on the Arithmetic of a Batch page.","ja":"七百二十ミリリットルの一本の背後に立つ玄米を、「一仕込みの算術」の頁の物質収支から割り出したもの。","zh":"一支 720 毫升酒瓶背後所站著的玄米量，依「一次仕込的算術」一頁的物質收支推算而得。"}},{"p":"cocktails","n":1,"c":{"en":"The same seven builds drawn to scale, so the arithmetic is visible.","ja":"同じ七つの配合を縮尺どおりに描いたもの。","zh":"同樣這七份配方按比例畫出，算術便看得見了。"}},{"p":"kanpai","n":1,"c":{"en":"The same courtesy, three different shapes across an evening.","ja":"同じ礼が、一夜のうちに三つの異なる形をとる。","zh":"同樣的禮節，在一個晚上會呈現三種不同的形狀。"}},{"p":"places","n":1,"c":{"en":"The same venues placed on the two axes that matter.","ja":"同じ店々を、意味のある二つの軸の上に置いたもの。","zh":"把同一批場所放在兩條真正重要的軸上。"}},{"p":"service","n":1,"c":{"en":"The clock that decides whether a restaurant can stock sake seriously.","ja":"料理店が日本酒を本気で置けるかどうかを決める時計。","zh":"這只時鐘，決定了一家餐廳能不能認真備清酒。"}},{"p":"itineraries","n":1,"c":{"en":"The brewing year, which begins on the first of October and is the axis everything in the trade is counted against.","ja":"酒造年度。十月一日に始まり、商いのあらゆる数がそれに対して数えられる軸である。","zh":"酒造年度：始於十月一日，也是這門生意裡一切數字所依據的軸線。"}},{"p":"visiting","n":1,"c":{"en":"Five kinds of room, placed by how broad the list is and how much the place is about the sake rather than the food.","ja":"五つの部屋を、品揃えの広さと、その店が料理ではなく酒をどれだけ主としているかによって置いたもの。","zh":"五種空間，依酒單的廣度、以及這個地方在多大程度上以酒（而非食物）為主軸來定位。"}},{"p":"health","n":1,"c":{"en":"What one drink actually contains, in grams of pure alcohol.","ja":"一杯が実際に含むものを、純アルコールのグラム数で。","zh":"一杯實際含有多少純酒精，以公克計。"}},{"p":"kojifamily","n":1,"c":{"en":"One mould, nine products, and the only thing that really changes is which enzyme is allowed to run.","ja":"一つの菌、九つの産物。そして本当に変わるのは、どの酵素に働くのを許すかということだけである。","zh":"一種黴菌，九樣產物，而真正改變的只有一件事：允許哪一種酵素放手去做。"}},{"p":"shochu","n":1,"c":{"en":"The kōji family after fermentation splits.","ja":"醗酵ののちに分かれる麹の一族。","zh":"發酵之後分岔的麴之家族。黴菌的菌系是第一個分枝，而那不是個小分枝：黃麴幾乎不自行產酸，黑麴與白麴則讓醪充滿檸檬…"}},{"p":"shochu","n":2,"c":{"en":"What survives the journey from pot to bottle, under the two pressures.","ja":"釜から瓶までの道を何が生き延びるか、二つの圧のもとで。","zh":"在兩種壓力之下，什麼能撐過從釜到瓶的這段路。"}},{"p":"kasu","n":1,"c":{"en":"The lees ratio is the percentage of the rice that never becomes sake, and it runs the wrong way round from what a yie…","ja":"粕歩合とは、酒にならなかった米の割合であり、歩留まりを考える読み手の予期とは逆に働く——数が高いほど、酒は良い。","zh":"粕步合是「從未成為清酒的那部分米」的百分比，而它的方向與講求出酒率的讀者所預期的恰好相反：數字越高，酒越好。"}},{"p":"mirin","n":1,"c":{"en":"The seasonings shelf as a tax diagram.","ja":"税の図としての調味料の棚。","zh":"作為稅務圖表的調味料貨架。"}},{"p":"mirin","n":2,"c":{"en":"The same two organisms, minus one.","ja":"同じ二つの生きもの、その一つを欠いたもの。","zh":"同樣的兩種生物，少了其中一種。"}},{"p":"world","n":1,"c":{"en":"When sake was first brewed in each country, on a broken axis — the left half is sixty years in which almost nothing h…","ja":"それぞれの国で日本酒が最初に造られた年を、折った軸の上に置いたもの。","zh":"各國最早釀出清酒的年份，畫在一條折斷的軸上：左半是除巴西之外幾乎什麼都沒發生的六十年，右半則是什麼都發生了的三…"}},{"p":"taiwan","n":1,"c":{"en":"One band, and the whole reason this page is short on history and long on the present.","ja":"一本の帯と、この頁が歴史に短く現在に長い理由のすべて。","zh":"一條色帶，以及本頁「歷史短、當代長」的全部原因。"}},{"p":"competitions","n":1,"c":{"en":"The same six events placed on the two axes that actually separate them: who is holding the glass, and whether the thi…","ja":"同じ六つの催しを、それらを実際に分ける二つの軸の上に置いたもの——杯を持つのが誰であるか、そしてそのなかのもの…","zh":"把同樣這六項賽事，放在真正區分它們的兩條軸上：拿著杯子的是誰，以及杯裡那樣東西是否在賣。"}},{"p":"industry","n":1,"c":{"en":"Taxed shipments of seishu, 1970–2021, in thousands of kilolitres.","ja":"清酒の課税移出数量、一九七〇年から二〇二一年まで、千キロリットル。","zh":"清酒的課稅移出數量，一九七〇至二〇二一年，單位為千公秉。"}},{"p":"industry","n":2,"c":{"en":"One brewing year, seen as cash rather than as sake.","ja":"一つの造りの年を、酒ではなく金として見たもの。","zh":"把一個釀造年看成金流，而不是看成酒。"}},{"p":"future","n":1,"c":{"en":"The three headline numbers on one scale.","ja":"三つの主要な数を一つの尺度の上に置いたもの。","zh":"三個主要數字放在同一個尺度上。"}},{"p":"debates","n":1,"c":{"en":"The eight arguments placed by how settled they are and by how much the answer would change what a reader should buy.","ja":"八つの論を、どれだけ決着しているかと、その答えが読み手の買うものをどれだけ変えるかによって置いたもの。","zh":"把這八個爭論，依「它們有多接近定案」以及「答案會多大程度改變讀者該買什麼」放置。"}},{"p":"learning","n":1,"c":{"en":"Every qualification worth naming, placed by what it actually certifies and by how far its recognition reaches.","ja":"名を挙げるに値するあらゆる資格を、それが実際に何を認めるか、そしてその認めがどこまで届くかによって置いたもので…","zh":"每一項值得一提的資格，依「它實際認證什麼」與「它的認可能傳多遠」放置。"}},{"p":"learning","n":2,"c":{"en":"The two halves of this page do not share a scale, and this figure is drawn to make that impossible to miss.","ja":"この頁の二つの半分は尺度を共にしない。","zh":"本頁的兩個半邊並不共用同一個尺度，而這張圖就是為了讓這件事無法被忽略而畫的。"}},{"p":"chronology","n":1,"c":{"en":"What this chronology is made of, counted.","ja":"この年表が何でできているかを、数えたもの。","zh":"這份年表由什麼構成——數出來看。"}},{"p":"tables","n":1,"c":{"en":"The ladder of measures, on a scale where every step of ten is the same distance.","ja":"容量の階梯を、十倍ごとに等間隔となる尺度の上に置いたもの。","zh":"容量的階梯，置於每十倍等距的尺度上。"}},{"p":"faq","n":1,"c":{"en":"Sake's strength and sake's dose are two different questions, and most of the confusion about how strong it is comes f…","ja":"日本酒の強さと、日本酒の量とは別の問いであり、その強さをめぐる混乱のほとんどは、後者を尋ねながら前者に答えるこ…","zh":"清酒有多烈，與清酒一次喝多少，是兩個不同的問題；而關於「它有多烈」的混淆，多半來自：你想問的是後者，得到的卻是…"}},{"p":"glossary","n":1,"c":{"en":"The glossary counted by category, which is a fair portrait of where the vocabulary actually lives.","ja":"用語集を分類ごとに数えたもの。","zh":"把詞彙表依類別數出來，這是一幅相當公允的肖像，顯示這套語彙實際上住在哪裡。"}},{"p":"sources","n":1,"c":{"en":"Four kinds of question, and how far any source can take you on each.","ja":"四つの種の問いと、いかなる資料もそこまでしか連れて行けぬという境目。","zh":"四種問題，以及任何資料在每一種上最多能帶你走多遠。"}}];
